function toggleBaseLayer(){if(!huntMap)return;let c=huntMap.getCenter(),z=huntMap.getZoom(),street=huntMap.hasLayer(streetLayer);if(street){huntMap.removeLayer(streetLayer);satelliteLayer.addTo(huntMap);localStorage.setItem('jaktlaget-map-layer','satellite')}else{huntMap.removeLayer(satelliteLayer);streetLayer.addTo(huntMap);localStorage.setItem('jaktlaget-map-layer','street')}huntMap.setView(c,z)}function initHuntMap(){let el=$('#mapCanvas');if(!el)return;el.innerHTML='';if(huntMap)huntMap.remove();huntMap=L.map(el,{zoomControl:true}).setView([58.6205,16.1825],14);let layerControl=L.control({position:'topleft'});layerControl.onAdd=()=>{let b=L.DomUtil.create('button','leaflet-bar mapLayerIcon');b.type='button';b.title='Växla karta/satellit';b.innerHTML='◫';L.DomEvent.disableClickPropagation(b);b.onclick=toggleBaseLayer;return b};layerControl.addTo(huntMap);satelliteLayer=L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',{maxZoom:19,attribution:'Esri'});streetLayer=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'OpenStreetMap'});let lp=localStorage.getItem('jaktlaget-map-layer')||'satellite';(lp==='street'?streetLayer:satelliteLayer).addTo(huntMap);decorateMap202(huntMap,true);draftLayer=L.polyline([],{color:'#52e482',weight:5,dashArray:'6 8'}).addTo(huntMap);drawBoundary(false);huntMap.fitBounds(boundaryLayer.getBounds(),{padding:[18,18]});huntMap.on('click',e=>{if(mapMode==='point'){draftTrack=[e.latlng];openMapForm(false)}else if(mapMode==='track'){draftTrack.push(e.latlng);draftLayer.setLatLngs(draftTrack);$('#finishTrack').hidden=draftTrack.length<2}else if(mapMode==='forecast'){forecastPoint=e.latlng;drawForecastSeat();let d=$('#forecastDialog');d.showModal?d.showModal():d.setAttribute('open','')}});drawMapData()}
