function cancelCurrentMapMode(){$('#mapForm').hidden=true;draftTrack=[];if(draftLayer)draftLayer.setLatLngs([]);setMapMode('point');toast('Åtgärden avbröts')}function reviewRange(){let v=$('#reviewPeriod').value,nowD=new Date();if(v==='year'){let y=+db.activeYear.split('/')[0];return new Date(y,6,1)}let days=+v;if(v==='custom'){let amount=Math.max(1,+$('#reviewAmount').value||1),unit=$('#reviewUnit').value;days=unit==='weeks'?amount*7:unit==='months'?amount*30:amount}return new Date(nowD.getTime()-days*86400000)}function filteredMapReports(){let from=reviewRange();return db.observations.filter(o=>Number.isFinite(o.latitude)&&Number.isFinite(o.longitude)&&new Date((o.date||'1970-01-01')+'T'+(o.time||'00:00'))>=from)}function openReview(){setMapMode('review');let d=$('#reviewDialog');d.showModal?d.showModal():d.setAttribute('open','');updateReviewSummary()}function updateReviewSummary(){let a=filteredMapReports();$('#reviewSummary').textContent=a.length+' rapporter matchar vald period.'}function applyReviewFilter(){let d=$('#reviewDialog');d.close?d.close():d.removeAttribute('open');drawMapData(filteredMapReports());toast('Visar '+filteredMapReports().length+' rapporter')}function csvCell(v){return '"'+String(v??'').replaceAll('"','""')+'"'}function exportReviewExcel(){let a=filteredMapReports(),head=['Datum','Tid','Typ','Djurslag','Klass','Antal','Observatör','Aktivitet','Riktning','Vindriktning','Vindstyrka m/s','Latitud','Longitud','Spårpunkter','Kommentar'],rows=a.map(o=>[o.date,o.time,o.droppings?'Spillning':o.track?.length>1?'Viltspår':'Viltobservation',o.species,o.animalClass,o.count,o.observerName,o.activity,o.direction,o.windDirection,o.windSpeed,o.latitude,o.longitude,o.track?.length||0,o.comment]);let csv='\ufeff'+[head,...rows].map(r=>r.map(csvCell).join(';')).join('\r\n'),x=document.createElement('a');x.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));x.download='katterum-kartobservationer-'+new Date().toISOString().slice(0,10)+'.csv';x.click();URL.revokeObjectURL(x.href);toast('Excel-fil exporterad')}function finishTrack(){if(draftTrack.length<2)return toast('Lägg minst två punkter');openMapForm(true)}
function saveBoundary(){save();drawBoundary(false);setMapMode('point');toast('Markgränsen sparades')}
function openMapForm(track){let n=new Date();$('#mapForm').hidden=false;$('#mapDate').value=n.toISOString().slice(0,10);$('#mapTime').value=n.toTimeString().slice(0,5);$('#mapDroppings').checked=false;$('#mapFormTitle').textContent=track?'Nytt viltspår':'Ny kartobservation';$('#saveMapReport').onclick=()=>saveMapObservation(track);$('#mapForm').scrollIntoView({behavior:'smooth',block:'start'})}
function compass(a,b){let d=Math.atan2(b.lng-a.lng,b.lat-a.lat)*180/Math.PI;if(d<0)d+=360;return dirs[1+Math.round(d/45)%8]}
function saveMapObservation(isTrack){let first=draftTrack[0],last=draftTrack[draftTrack.length-1],m=member($('#mapObserver').value),dir=isTrack?compass(first,last):$('#mapDirection').value,o={id:uid('obs'),year:db.activeYear,date:$('#mapDate').value||new Date().toISOString().slice(0,10),time:$('#mapTime').value||new Date().toTimeString().slice(0,5),observerType:'member',observerId:m.id,observerName:m.name,visualObservation:$('#mapVisualObservation').checked,droppings:$('#mapDroppings').checked,fieldAnimal:$('#mapFieldAnimal').checked,species:$('#mapSpecies').value,animalClass:$('#mapClass').value,count:Math.max(1,+$('#mapCount').value||1),place:'Kartposition',direction:dir,activity:$('#mapActivity').value,windDirection:$('#mapWindDirection').value,windSpeed:Math.max(0,+$('#mapWindSpeed').value||0),comment:$('#mapComment').value,latitude:first.lat,longitude:first.lng,track:isTrack?draftTrack.map(x=>({lat:x.lat,lng:x.lng})):[],createdAt:now(),updatedAt:now()};db.observations.unshift(o);audit(o.droppings?'Spillning registrerad':isTrack?'Viltspår registrerat':'Kartobservation registrerad',`${o.species}, ${o.count} djur, vind ${o.windDirection} ${o.windSpeed} m/s`);save();$('#mapForm').hidden=true;draftTrack=[];if(draftLayer)draftLayer.setLatLngs([]);drawMapData();renderMappedList();toast(isTrack?'Spår och vind sparades':'Observation och vind sparades')}
function windSvg(o){if(!o.windDirection||o.windDirection==='Okänd')return '';let d=dirDeg[o.windDirection]||0,len=55+Math.min(45,(+o.windSpeed||0)*4);return `<div class="windBadge"><span class="windArrow" style="--rot:${d+180}deg;--len:${len}px">➤</span><b>Vind från ${o.windDirection}</b><small>${o.windSpeed||0} m/s</small></div>`}
function drawMapData(source=null){if(!huntMap)return;mapLayers.forEach(x=>huntMap.removeLayer(x));mapLayers=[];(source||db.observations.filter(o=>Number.isFinite(o.latitude)&&Number.isFinite(o.longitude))).forEach(o=>{let html=`<b>${o.droppings?'Spillning · ':''}${esc(o.species)} · ${o.count} ${o.droppings?'fynd':'djur'}</b><br>${esc(o.date)} ${esc(o.time||'')}<br>Djur: ${esc(o.direction||'Okänd')}<br>${windSvg(o)}`;let mk=L.circleMarker([o.latitude,o.longitude],{radius:Math.min(15,7+o.count/2),color:'#fff',weight:2,fillColor:o.droppings?'#9b6b43':'#43db79',fillOpacity:.9}).bindPopup(html).addTo(huntMap);mapLayers.push(mk);if(o.track&&o.track.length>1){let line=L.polyline(o.track.map(x=>[x.lat,x.lng]),{color:'#ffd166',weight:4}).bindPopup(html+'<br>Viltspår');line.addTo(huntMap);mapLayers.push(line)}})}
function renderMappedList(){let e=$('#mappedList');if(!e)return;let a=db.observations.filter(o=>Number.isFinite(o.latitude)&&Number.isFinite(o.longitude)).slice(0,8);e.innerHTML=a.map(o=>`<div class="recordCard"><div><b>${esc(o.species)} · ${o.count} djur</b><br>${esc(o.date)} ${esc(o.time||'')} · ${o.droppings?'Spillning':o.track&&o.track.length>1?'Spår':'Punkt'}<small>Djur ${esc(o.direction||'Okänd')} · Vind från ${esc(o.windDirection||'ej angiven')} ${o.windSpeed??''} m/s</small></div><button class="danger" onclick="deleteMappedObs('${o.id}')">Radera</button></div>`).join('')||'<p class="muted">Inga kartlagda observationer ännu.</p>'}
let forecastPoint=null,forecastVisuals=[];function clearForecast(){forecastVisuals.forEach(x=>huntMap&&huntMap.removeLayer(x));forecastVisuals=[];forecastPoint=null;$('#forecastSide').hidden=true;$('#clearForecast').hidden=true;setMapMode('point');toast('Jaktprognosen borttagen')}function drawForecastSeat(){forecastVisuals.forEach(x=>huntMap.removeLayer(x));forecastVisuals=[];forecastVisuals.push(L.marker(forecastPoint,{icon:L.divIcon({className:'forecastSeat',html:'⌖',iconSize:[42,42],iconAnchor:[21,21]})}).addTo(huntMap))}async function runForecast(e){if(e)e.preventDefault();if(!forecastPoint)return;let d=$('#forecastDialog');d.close?d.close():d.removeAttribute('open');$('#forecastSide').hidden=false;$('#clearForecast').hidden=false;let iso=$('#forecastDate').value+'T'+$('#forecastTime').value,r=$('#forecastResult');r.innerHTML='<p class="muted">Hämtar prognos…</p>';try{let u=`https://api.open-meteo.com/v1/forecast?latitude=${forecastPoint.lat}&longitude=${forecastPoint.lng}&hourly=wind_speed_10m,wind_direction_10m,temperature_2m,apparent_temperature,precipitation_probability,precipitation,rain,showers,snowfall,weather_code,cloud_cover,is_day,visibility&wind_speed_unit=ms&timezone=Europe%2FStockholm&forecast_days=16`,j=await(await fetch(u)).json(),i=j.hourly.time.reduce((b,t,k)=>Math.abs(new Date(t)-new Date(iso))<Math.abs(new Date(j.hourly.time[b])-new Date(iso))?k:b,0),wd=j.hourly.wind_direction_10m[i],ws=j.hourly.wind_speed_10m[i];drawForecastWind(wd,ws);let h=+$('#forecastTime').value.split(':')[0],rows=mainSpecies.map(sp=>{let a=db.observations.filter(o=>o.species===sp&&Number.isFinite(o.latitude)),score=a.reduce((n,o)=>{let x=(o.latitude-forecastPoint.lat)*111,y=(o.longitude-forecastPoint.lng)*60,km=Math.sqrt(x*x+y*y),oh=+(o.time||'12:00').split(':')[0];return n+Math.max(0,1-km/3)*Math.max(0,1-Math.abs(oh-h)/8)*Math.sqrt(o.count||1)},0);return{sp,score,n:a.length}}),sum=rows.reduce((n,x)=>n+x.score,0),ptype=j.hourly.snowfall[i]>0?'Snö':j.hourly.showers[i]>0?'Skurar':j.hourly.rain[i]>0?'Regn':'Ingen';r.innerHTML=`<h3>Väder vid sittplatsen</h3><div class="forecastGrid"><div>Vind<b>${dirs[1+Math.round(wd/45)%8]} · ${ws.toFixed(1)} m/s</b></div><div>Temperatur<b>${j.hourly.temperature_2m[i].toFixed(1)} °C</b></div><div>Molnighet<b>${j.hourly.cloud_cover[i]}%</b></div><div>Nederbörd<b>${ptype} · ${j.hourly.precipitation[i].toFixed(1)} mm</b></div><div>Ljus<b>${j.hourly.is_day[i]?'Dagsljus':'Mörkt/skymning'}</b></div><div>Sikt<b>${(j.hourly.visibility[i]/1000).toFixed(1)} km</b></div></div><h3>Chans vid vald punkt</h3>${rows.map(x=>`<div class="forecastChance"><span>${x.sp}<small>${x.n} kartobs</small></span><b>${sum?Math.round(x.score/sum*100):0}%</b></div>`).join('')}`}catch(e){r.innerHTML='<p class="muted">Prognosen kunde inte hämtas.</p>'}}function drawForecastWind(wd,ws){forecastVisuals.slice(1).forEach(x=>huntMap.removeLayer(x));forecastVisuals=forecastVisuals.slice(0,1);let f=(wd+180)*Math.PI/180,c=Math.cos(forecastPoint.lat*Math.PI/180),e=111320,l=140+ws*10,p=f+Math.PI/2;[-1,-.66,-.33,0,.33,.66,1].forEach((q,i)=>{let a=f+q*12.5*Math.PI/180,la=forecastPoint.lat+Math.cos(p)*q*5/e,lo=forecastPoint.lng+Math.sin(p)*q*5/e/c,pts=[];for(let n=0;n<=26;n++){let t=n/26,w=Math.sin(t*Math.PI*2+i)*2/e;pts.push([la+Math.cos(a)*l*t/e+Math.cos(p)*w,lo+(Math.sin(a)*l*t/e+Math.sin(p)*w)/c])}forecastVisuals.push(L.polyline(pts,{color:'#68cef7',weight:2.5,opacity:.82}).addTo(huntMap))})}
window.deleteMappedObs=id=>{if(confirm('Radera observationen även från viltrapporteringen?')){db.observations=db.observations.filter(x=>x.id!==id);save();drawMapData();renderMappedList()}}

function huntstats(){let hs=db.hunts.filter(x=>x.year===db.activeYear),md={},gd={};hs.forEach(h=>{h.participants.forEach(x=>md[x]=(md[x]||0)+1);h.guests.forEach(x=>gd[x]=(gd[x]||0)+1)});let typeRows=['Vakjakt','Pyrschjakt','Drevjakt'].map(t=>{let a=hs.filter(x=>x.type===t);return `<div class="statLine"><span>${t}</span><b>${a.length} jakter · ${a.reduce((n,x)=>n+x.participants.length+x.guests.length,0)} jaktdagar</b></div>`}).join('');shell('Jaktstatistik',`<div class="subKpis four"><div><span>Jakter</span><b>${hs.length}</b></div><div><span>Medlemsdagar</span><b>${Object.values(md).reduce((a,b)=>a+b,0)}</b></div><div><span>Gästdagar</span><b>${Object.values(gd).reduce((a,b)=>a+b,0)}</b></div><div><span>Lagets jaktdagar</span><b>${Object.values(md).reduce((a,b)=>a+b,0)+Object.values(gd).reduce((a,b)=>a+b,0)}</b></div></div><h3>Jaktformer</h3>${typeRows}<h3>Medlemmar</h3>${db.members.map(m=>`<div class="statLine"><span>${m.name}</span><b>${md[m.id]||0}</b></div>`).join('')}<h3>Gäster</h3>${Object.entries(gd).map(x=>`<div class="statLine"><span>${esc(x[0])}</span><b>${x[1]}</b></div>`).join('')||'<p class="muted">Inga gäster.</p>'}`)}
function obsstats(){let a=db.observations.filter(x=>x.year===db.activeYear),s={};a.forEach(x=>{s[x.species]=s[x.species]||[0,0];s[x.species][0]++;s[x.species][1]+=x.count});shell('Observationsstatistik',`<p class="muted">Observerade djur är inte samma sak som unika djur. Samma djur kan ha observerats flera gånger.</p><div class="subKpis"><div><span>Observationer</span><b>${a.length}</b></div><div><span>Observerade djur</span><b>${a.reduce((n,x)=>n+x.count,0)}</b></div></div>${Object.entries(s).map(x=>`<div class="statLine"><span>${x[0]}</span><b>${x[1][0]} obs · ${x[1][1]} djur</b></div>`).join('')}`)}
function discards(){let x=db.animals.filter(a=>a.year===db.activeYear&&(a.discarded||a.species==='Annat'));shell('Kassation och övrigt vilt',x.map(a=>`<div class="recordCard"><div><b>${a.species==='Annat'?(a.otherSpecies||'Annat'):a.species} · ${a.type}</b><br>${a.date} · ${a.place}<small>${a.discarded?'Kasserat: '+a.discardReason:'Övrigt vilt'}</small></div><button onclick="editAnimal('${a.id}')">Ändra</button></div>`).join('')||'<p class="muted">Inga poster.</p>')}
function goals(){shell('Avskjutningsmål, utfall',`<label>Djurslag<select id="goalSpecies">${mainSpecies.map(x=>`<option>${x}</option>`).join('')}</select></label><div id="goalBody"></div>`);$('#goalSpecies').onchange=drawGoal;drawGoal()}function drawGoal(){let sp=$('#goalSpecies').value,g=db.goals[sp],a=normalAnimals().filter(x=>x.species===sp).sort((x,y)=>x.date.localeCompare(y.date)),ad=a.filter(x=>x.age==='Vuxen').length,yo=a.length-ad,target=g.adult+g.young,max=Math.max(1,target,a.length),pts=a.map((x,i)=>`${35+i*240/Math.max(1,a.length-1)},${145-(i+1)/max*110}`).join(' '),gy=145-target/max*110;$('#goalBody').innerHTML=`${goalRow('Vuxen',ad,g.adult)}${goalRow('Ungdjur',yo,g.young)}<p class="muted">Mål ändras under Inställningar → Jaktår och mål. Period ${g.start} till ${g.end}.</p><div class="timeline goalChart"><svg viewBox="0 0 300 180"><line x1="35" y1="145" x2="280" y2="145" stroke="#789"/><line x1="35" y1="22" x2="35" y2="145" stroke="#789"/><line x1="35" y1="${gy}" x2="280" y2="${gy}" stroke="#ffd166" stroke-dasharray="6 4"/><text x="40" y="${Math.max(16,gy-5)}" fill="#ffd166">Mål ${target}</text><text x="145" y="170" fill="#9fb5aa">Tid under jaktåret</text><text x="9" y="112" fill="#9fb5aa" transform="rotate(-90 9 112)">Ackumulerat antal</text><polyline points="${pts}" fill="none" stroke="#43db79" stroke-width="4"/></svg></div>`}function goalRow(n,v,t){return `<div class="goalRow"><div><b>${n}</b><span>${v} av ${t}</span></div><i><b style="width:${t?Math.min(100,v/t*100):0}%"></b></i></div>`}
function passview(){shell('Passöversikt',`<div class="two"><label>Välj pass<select id="viewPass">${db.passes.map(x=>`<option>${esc(x.name)}</option>`).join('')}</select></label><label>Jaktår<select id="passViewYear">${years().map(y=>`<option ${y===db.activeYear?'selected':''}>${y}</option>`).join('')}</select></label></div><button id="passViewWeather" class="secondary">Visa vind för vald tid</button><div id="passViewBody"></div>`);$('#viewPass').onchange=drawPassView;$('#passViewYear').onchange=drawPassView;$('#passViewWeather').onclick=()=>{let p=db.passes.find(x=>x.name===$('#viewPass').value);if(!p||!Number.isFinite(p.latitude))return toast('Passet saknar kartposition');forecastForPass(p.id)};drawPassView()}function drawPassView(){let p=$('#viewPass').value,y=$('#passViewYear').value,a=db.animals.filter(x=>x.place===p&&x.year===y),h=db.hunts.filter(x=>x.place===p&&x.year===y),o=db.observations.filter(x=>x.place===p&&x.year===y);$('#passViewBody').innerHTML=`<div class="subKpis twoKpi"><div><span>Fällda</span><b>${a.length}</b></div><div><span>Observationer</span><b>${o.length}</b></div></div><h3>Fällt vilt</h3>${a.map(x=>`<div class="statLine"><span>${x.date} ${x.species}</span><b>${x.type}</b></div>`).join('')||'<p class="muted">Inga poster.</p>'}<h3>Jaktformer</h3>${['Vakjakt','Pyrschjakt','Drevjakt'].map(t=>`<div class="statLine"><span>${t}</span><b>${h.filter(x=>x.type===t).length}</b></div>`).join('')}`}
function infoSymbol(p){return p==='critical'?'⛔':p==='important'?'⚠':'ℹ'}function infoLabel(p){return p==='critical'?'Måste läsas':p==='important'?'Viktig information':'Allmän information'}function infoCard(x){return `<div class="infoCard info-${x.priority||'general'}"><span class="infoSymbol">${infoSymbol(x.priority)}</span><div><b>${infoLabel(x.priority)}</b><p>${esc(x.text)}</p><small>${esc(x.author||'Ej angivet')} · ${x.date?new Date(x.date).toLocaleString('sv-SE'):''}</small></div></div>`}
function info(){let posts=(db.infoPosts||[]).slice().reverse(),authors=db.members.filter(x=>x.active!==false);shell('Information',`<div class="infoList">${posts.length?posts.map(x=>infoCard(x)+`<button class="danger infoDelete" onclick="deleteInfo('${x.id}')">Radera</button>`).join(''):'<p class="muted">Ingen information har lagts till.</p>'}</div><div class="stackForm infoForm"><label>Författare<select id="infoAuthor">${authors.map(m=>`<option>${esc(m.name)}</option>`).join('')}</select></label><label>Prioritet<select id="infoPriority"><option value="general">ℹ Allmän information</option><option value="important">⚠ Viktig information</option><option value="critical">⛔ Måste läsas</option></select></label><label>Information<textarea id="teamInfo" rows="6"></textarea></label><button id="saveInfo">Lägg till information</button></div>`);$('#saveInfo').onclick=()=>{let text=$('#teamInfo').value.trim();if(!text)return toast('Skriv informationen');db.infoPosts=db.infoPosts||[];db.infoPosts.push({id:uid('info'),text,author:$('#infoAuthor').value,priority:$('#infoPriority').value,date:now()});save();info();toast('Information publicerad')}}
window.deleteInfo=id=>{if(confirm('Radera informationen?')){db.infoPosts=db.infoPosts.filter(x=>x.id!==id);save();info()}}
function chat(){let authors=db.members.filter(x=>x.active!==false);shell('Chatt',`${db.messages.map(x=>`<div class="event chatEvent"><b>${esc(x.author||'Ej angivet')}</b><span>${esc(x.text)}</span><small>${x.date?new Date(x.date).toLocaleString('sv-SE'):''}</small></div>`).join('')}<div class="stackForm"><label>Vem skriver?<select id="chatAuthor">${authors.map(m=>`<option>${esc(m.name)}</option>`).join('')}</select></label><label>Meddelande<input id="chatText" placeholder="Meddelande"></label><button id="sendChat">Skicka</button></div>`);$('#sendChat').onclick=()=>{let t=$('#chatText').value.trim();if(t){db.messages.push({id:uid('msg'),author:$('#chatAuthor').value,text:t,date:now()});save();chat()}}}
function calendar(){let cards=db.events.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(x=>{let regs=x.registrations||[],guests=regs.reduce((n,r)=>n+(+r.guestCount||0),0),total=regs.length+guests,names=regs.map(r=>{let m=member(r.memberId),gn=(r.guestNames||[]).filter(Boolean);return `${m?m.name:'Okänd'}${r.guestCount?` + ${r.guestCount} gäst${r.guestCount===1?'':'er'}${gn.length?' ('+gn.join(', ')+')':''}`:''}`}).join(' · ');return `<div class="calendarCard"><div><b>${x.date}</b><span>${esc(x.title)}</span><small>${total} personer: ${esc(names||'Ingen anmäld')}</small></div><div class="calendarActions"><button onclick="openEventSignup('${x.id}')">Anmäl</button><button class="danger" onclick="deleteEvent('${x.id}')">Radera</button></div></div>`}).join('')||'<p class="muted">Inga aktiviteter.</p>';shell('Kalender',`<div class="calendarList">${cards}</div><div class="stackForm calendarForm"><label>Datum<input id="eventDate" type="date"></label><label>Aktivitet<input id="eventTitle" placeholder="Aktivitet"></label><button id="addEvent">Lägg till</button></div>`);$('#addEvent').onclick=()=>{if($('#eventDate').value&&$('#eventTitle').value.trim()){db.events.push({id:uid('event'),date:$('#eventDate').value,title:$('#eventTitle').value.trim(),registrations:[]});save();calendar()}}}
window.openEventSignup=id=>{let ev=db.events.find(x=>x.id===id);if(!ev)return;ev.registrations=ev.registrations||[];shell('Anmälan',`<button class="backBtn" onclick="calendar()">‹ Kalender</button><h3>${esc(ev.title)} · ${ev.date}</h3><div class="stackForm"><label>Medlem<select id="signupMember">${db.members.filter(m=>m.active!==false).map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label><label>Antal gäster<select id="signupGuests">${Array.from({length:11},(_,i)=>`<option value="${i}">${i}</option>`).join('')}</select></label><label id="guestNamesBox" hidden>Gästnamn, valfritt, ett per rad<textarea id="signupGuestNames" placeholder="Exempel: Anna Andersson"></textarea></label><button id="saveSignup">Spara anmälan</button></div><h3>Anmälda</h3><div id="signupList"></div>`);let toggle=()=>$('#guestNamesBox').hidden=+$('#signupGuests').value===0;$('#signupGuests').onchange=toggle;toggle();$('#saveSignup').onclick=()=>{let mid=$('#signupMember').value,count=+$('#signupGuests').value||0,names=$('#signupGuestNames').value.split('\n').map(x=>x.trim()).filter(Boolean).slice(0,count),r=ev.registrations.find(x=>String(x.memberId)===String(mid)),obj={memberId:mid,guestCount:count,guestNames:names};if(r)Object.assign(r,obj);else ev.registrations.push(obj);save();openEventSignup(id);toast('Anmälan sparades')};drawSignupList(ev)}
function drawSignupList(ev){let e=$('#signupList');if(!e)return;e.innerHTML=(ev.registrations||[]).map(r=>{let m=member(r.memberId),gn=(r.guestNames||[]).filter(Boolean);return `<div class="recordCard"><div><b>${esc(m?.name||'Okänd')}</b><small>${r.guestCount?`${r.guestCount} gäst${r.guestCount===1?'':'er'}${gn.length?' · '+esc(gn.join(', ')):''}`:'Inga gäster'}</small></div><button class="danger" onclick="removeSignup('${ev.id}','${r.memberId}')">Ta bort</button></div>`}).join('')||'<p class="muted">Ingen är anmäld ännu.</p>'}
window.removeSignup=(eid,mid)=>{let ev=db.events.find(x=>x.id===eid);ev.registrations=(ev.registrations||[]).filter(x=>String(x.memberId)!==String(mid));save();openEventSignup(eid)}
window.deleteEvent=id=>{if(confirm('Radera aktiviteten?')){db.events=db.events.filter(x=>x.id!==id);save();calendar()}}
function contacts(){shell('Kontakter',`<div class="contactList">${db.members.filter(x=>x.active!==false).map(x=>`<button onclick="openContact('${x.id}')"><b>${x.name}</b><span>Visa kontaktinformation</span></button>`).join('')}</div>`)}window.openContact=id=>{let m=member(id),tel=String(m.phone||'').replace(/[^+\d]/g,'');shell(m.name,`<button class="backBtn" onclick="contacts()">‹ Kontakter</button><div class="contactDetail"><div><span>Telefon</span>${tel?`<a class="callLink" href="tel:${tel}">${esc(m.phone)}</a>`:'<b>Ej angivet</b>'}</div><div><span>E-post</span><b>${esc(m.email||'Ej angivet')}</b></div><div><span>Kommentar</span><b>${esc(m.comment||'Ej angivet')}</b></div></div>`)}
