/* v2.4.0 cloud pass registry */
(function(){
 const VERSION='2.4.0',TEAM='katterums-jaktlag',CACHE='katterums-v240-passes';
 let cloudReady240=false,syncTimer240=null,lastFingerprint240='';
 const normalizePass240=p=>({id:String(p.id),name:p.name,area:p.area||'',latitude:p.latitude==null?null:+p.latitude,longitude:p.longitude==null?null:+p.longitude,active:p.active!==false,markerType:p.marker_type||p.markerType||'pass',photo:p.photo||'',externalId:p.externalId||null});
 const fingerprint240=a=>JSON.stringify((a||[]).map(p=>[String(p.id),p.name,p.area||'',Number.isFinite(p.latitude)?p.latitude:null,Number.isFinite(p.longitude)?p.longitude:null,p.active!==false,p.markerType||'pass']));
 function cache240(){try{localStorage.setItem(CACHE,JSON.stringify(db.passes||[]))}catch{}}
 async function push240(force=false){
   if(!cloudReady240||!window.KatterumsCloud?.upsertPasses)return;
   const fp=fingerprint240(db.passes);if(!force&&fp===lastFingerprint240)return;
   const r=await KatterumsCloud.upsertPasses(db.passes);if(!r.ok){toast('Pass kunde inte synkas: '+r.error);return}
   lastFingerprint240=fp;cache240();const e=$('#storageStatus');if(e)e.textContent='Molnläge · pass synkade';
 }
 function schedule240(){clearTimeout(syncTimer240);syncTimer240=setTimeout(()=>push240(false),250)}
 async function bootstrap240(){
   if(!window.KatterumsCloud?.listPasses)return;
   const r=await KatterumsCloud.listPasses();
   if(!r.ok){toast('Kunde inte läsa pass från Supabase: '+r.error);return}
   const real=(r.passes||[]).filter(p=>p.id!=='test'&&p.name!=='Testpass');
   if(!real.length){
     db.passes=(db.passes||[]).map(p=>({...p,latitude:null,longitude:null}));
     const z=await KatterumsCloud.upsertPasses(db.passes);if(!z.ok){toast('Kunde inte skapa passregistret: '+z.error);return}
     if((r.passes||[]).some(p=>p.id==='test'))await KatterumsCloud.deletePass('test');
   }else db.passes=real.map(normalizePass240);
   cloudReady240=true;lastFingerprint240=fingerprint240(db.passes);cache240();
   localStorage.setItem('jaktlaget-v240',JSON.stringify(db));
   renderAll();if($('#settings')?.classList.contains('active'))settingsHome();
   const e=$('#storageStatus');if(e)e.textContent='Molnläge · pass från Supabase';
 }
 const oldSave240=save;
 save=function(){oldSave240();if(cloudReady240)schedule240()};
 const oldToggle240=window.togglePass;
 window.togglePass=function(id){oldToggle240(id);schedule240()};
 function mark240(){let e=$('#appVersion227');if(e)e.textContent='Jaktlagsappen · v'+VERSION;document.title='Jaktlaget '+VERSION;$$('.versionFooter227').forEach(x=>x.textContent='Katterums jaktlag · Jaktlagsappen v'+VERSION)}
 mark240();setTimeout(mark240,0);
 const wait=setInterval(()=>{if(window.KatterumsCloud?.client&&window.KATTERUMS_V2111?.getCurrentUser?.()){clearInterval(wait);bootstrap240()}},150);
 window.KATTERUMS_V240={version:VERSION,bootstrap:bootstrap240,sync:()=>push240(true)};
})();




