 function mark(){let e=$('#appVersion227');if(e)e.textContent='Jaktlagsappen · v'+VERSION;document.title='Jaktlaget '+VERSION;$$('.versionFooter227').forEach(x=>x.textContent='Katterums jaktlag · Jaktlagsappen v'+VERSION)}
 mark();setTimeout(mark,0);setTimeout(mark,500);
